import java.util.*;

public class Solution {
  public static boolean solve(int[][] a, int x) {
    if (a.length == 0 || a[0].length == 0) return false;
    int r = 0, c = a[0].length - 1;
    while (r < a.length && c >= 0) {
      if (a[r][c] == x) return true;
      if (a[r][c] > x) c--;
      else r++;
    }
    return false;
  }

  public static void main(String[] args) {
    System.out.println(solve(new int[][] {{1, 4, 7}, {2, 5, 8}, {3, 6, 9}}, 6));
  }
}

Find Peak Element in a 2D Matrix.source:
import java.util.*;

public class Solution {
  public static int[] solve(int[][] a) {
    if (a.length == 0 || a[0].length == 0) return new int[] {-1, -1};
    int l = 0, r = a[0].length - 1;
    while (l <= r) {
      int c = l + (r - l) / 2, row = 0;
      for (int i = 1; i < a.length; i++) if (a[i][c] > a[row][c]) row = i;
      long left = c == 0 ? Long.MIN_VALUE : a[row][c - 1],
          right = c + 1 == a[0].length ? Long.MIN_VALUE : a[row][c + 1];
      if (a[row][c] > left && a[row][c] > right) return new int[] {row, c};
      if (left > a[row][c]) r = c - 1;
      else l = c + 1;
    }
    return new int[] {-1, -1};
  }

  public static void main(String[] args) {
    System.out.println(Arrays.toString(solve(new int[][] {{1, 4}, {3, 2}})));
  }
}

Median of a Row Wise Sorted Matrix.source:
import java.util.*;

public class Solution {
  public static int solve(int[][] a) {
    if (a.length == 0 || a[0].length == 0) throw new IllegalArgumentException();
    int n = a[0].length;
    long total = (long) a.length * n;
    if (total % 2 == 0) throw new IllegalArgumentException("odd cell count required");
    long l = Integer.MAX_VALUE, r = Integer.MIN_VALUE;
    for (int[] row : a) {
      l = Math.min(l, row[0]);
      r = Math.max(r, row[n - 1]);
    }
    while (l < r) {
      long mid = l + (r - l) / 2, count = 0;
      for (int[] row : a) {
        int lo = 0, hi = n;
        while (lo < hi) {
          int m = lo + (hi - lo) / 2;
          if (row[m] <= mid) lo = m + 1;
          else hi = m;
        }
        count += lo;
      }
      if (count > total / 2) r = mid;
      else l = mid + 1;
    }
    return (int) l;
  }

  public static void main(String[] args) {
    System.out.println(solve(new int[][] {{1, 3, 5}, {2, 6, 9}, {3, 6, 9}}));
  }
}
